#include "../src/microvm/gui/WindowPresenter.h"
#include <Windows.h>
#include <iostream>
#include <stdexcept>
#include <vector>
namespace d=guardian::desktop;namespace p=guardian::presentation;namespace w=av::microvm::window_session;
namespace {
unsigned checks=0;void Check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
struct Search {uint64_t session;std::vector<HWND> found;};
std::vector<HWND> Windows(uint64_t session){Search search{session,{}};EnumWindows([](HWND h,LPARAM raw)->BOOL {auto& s=*reinterpret_cast<Search*>(raw);DWORD pid=0;GetWindowThreadProcessId(h,&pid);if(pid!=GetCurrentProcessId())return TRUE;wchar_t name[128]{};GetClassNameW(h,name,128);if(lstrcmpW(name,L"Aegis.MiniNT.WindowBridge.12F")==0&&uint64_t(GetPropW(h,L"Aegis.Session12F"))==s.session)s.found.push_back(h);return TRUE;},LPARAM(&search));return search.found;}
template<class F>void Wait(F ready,const char* why){const auto start=GetTickCount64();while(!ready()&&GetTickCount64()-start<3000)Sleep(10);Check(ready(),why);}
w::Frame Frame(uint64_t session){w::Frame f;f.session=session;f.number=1;f.metadata.count=1;auto& root=f.metadata.windows[0];root.handle=10;root.pid=1;root.tid=2;root.style=WS_POPUP|WS_VISIBLE;root.flags=1;root.bounds=root.client={100,100,220,180};root.title[0]='A';w::Image image;image.window=10;image.width=120;image.height=80;image.pixels.assign(120*80,0xFF123456);f.images.push_back(std::move(image));return f;}
COLORREF Sample(HWND h){BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=1;info.bmiHeader.biHeight=-1;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* data=nullptr;const auto bitmap=CreateDIBSection(nullptr,&info,DIB_RGB_COLORS,&data,nullptr,0);const auto dc=CreateCompatibleDC(nullptr);Check(bitmap&&dc&&data,"Native capture allocation");const auto previous=SelectObject(dc,bitmap);SetViewportOrgEx(dc,-5,-5,nullptr);SendMessageW(h,WM_PRINTCLIENT,WPARAM(dc),PRF_CLIENT);GdiFlush();const auto value=*static_cast<uint32_t*>(data)&0xFFFFFF;SelectObject(dc,previous);DeleteDC(dc);DeleteObject(bitmap);return value;}
}
int main(){try{
    const auto dpiContext=SetThreadDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);Check(dpiContext!=nullptr,"DPI test context");const auto sentinel=CreateWindowExW(0,L"STATIC",L"12F outside sentinel",WS_POPUP,5,5,20,20,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);Check(sentinel!=nullptr,"Outside sentinel");
    w::Presenter a({},true),b({},true);auto first=Frame(111),second=Frame(222);second.images[0].pixels.assign(120*80,0xFFABCDEF);a.Display(first);b.Display(second);Wait([]{return Windows(111).size()==1&&Windows(222).size()==1;},"Independent native windows");const auto ha=Windows(111).front(),hb=Windows(222).front();Check(ha!=hb&&IsWindowVisible(ha)&&IsWindowVisible(hb),"Separate HWNDs");Check(Sample(ha)==0x123456&&Sample(hb)==0xABCDEF,"Independent native client pixels");while(a.Poll().kind!=p::Kind::None){}while(b.Poll().kind!=p::Kind::None){}
    SendMessageW(ha,WM_KEYDOWN,'A',1|(30<<16));const auto e=a.Poll();Check(e.session==111&&e.window==10&&e.kind==p::Kind::KeyDown&&e.key=='A'&&e.scan==30,"Native key targets exact guest/session");Check(b.Poll().kind==p::Kind::None,"No input in other session");SendMessageW(ha,WM_UNICHAR,0x1F600,0);Check(a.Poll().key==0x1F600,"Native Unicode scalar");
    ShowWindow(ha,SW_SHOWMINNOACTIVE);Wait([&]{return IsIconic(ha)!=FALSE;},"Native minimize");ShowWindow(ha,SW_SHOWNOACTIVATE);Wait([&]{return !IsIconic(ha);},"Native restore");
    RECT scaled{150,150,330,270};SendMessageW(ha,WM_DPICHANGED,MAKEWPARAM(144,144),LPARAM(&scaled));RECT scaledClient{};GetClientRect(ha,&scaledClient);Check(scaledClient.right==180&&scaledClient.bottom==120&&Sample(ha)==0x123456,"Synthetic DPI message resizes and scales native pixels");RECT original{100,100,220,180};SendMessageW(ha,WM_DPICHANGED,MAKEWPARAM(96,96),LPARAM(&original));while(a.Poll().kind!=p::Kind::None){}
    {w::Presenter opaque({},true);auto forged=Frame(333);forged.metadata.windows[0].handle=uint64_t(sentinel);forged.images[0].window=uint64_t(sentinel);opaque.Display(forged);Wait([]{return Windows(333).size()==1;},"Opaque guest identifier creates a fresh HWND");Check(Windows(333).front()!=sentinel&&IsWindow(sentinel),"Guest cannot alias a host HWND");w::Frame gone;gone.session=333;gone.number=2;opaque.Display(gone);opaque.Finish();Check(IsWindow(sentinel)&&Windows(333).empty(),"Forged identifier cleanup cannot destroy outside HWND");}
    auto modal=first;modal.number=2;modal.metadata.count=2;modal.metadata.windows[0].style|=WS_DISABLED;auto& popup=modal.metadata.windows[1];popup=modal.metadata.windows[0];popup.handle=20;popup.owner=10;popup.style=WS_POPUP|WS_VISIBLE;popup.bounds=popup.client={130,130,250,210};popup.title[0]='B';auto image=modal.images[0];image.window=20;image.pixels.assign(120*80,0xFF445566);modal.images.push_back(std::move(image));a.Display(modal);Wait([&]{return Windows(111).size()==2&&!IsWindowEnabled(ha);},"Modal disables owner");HWND popupHandle=nullptr;for(auto h:Windows(111))if(h!=ha)popupHandle=h;Check(popupHandle&&GetWindow(popupHandle,GW_OWNER)==ha&&Sample(popupHandle)==0x445566,"Native owned dialog");
    auto restored=first;restored.number=3;a.Display(restored);Wait([&]{return Windows(111).size()==1&&IsWindowEnabled(ha);},"Modal cleanup and owner restored");
    bool rejected=false;try{a.Display(second);}catch(const std::exception&){rejected=true;}Check(rejected,"Cross-session frame rejected before presentation");
    w::Frame empty;empty.session=111;empty.number=4;a.Display(empty);Wait([]{return Windows(111).empty();},"Guest close destroys native HWND");a.Finish();b.Finish();Check(Windows(111).empty()&&Windows(222).empty()&&IsWindow(sentinel),"All native resources cleaned, outside window intact");const auto objects=GetGuiResources(GetCurrentProcess(),GR_GDIOBJECTS);
    for(uint32_t stage=1;stage<=2;++stage){const auto captures=std::filesystem::temp_directory_path()/("aegis12f-resource-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64())+"-"+std::to_string(stage));Check(std::filesystem::create_directory(captures),"Resource test directory");w::Presenter resource({},true,captures);resource.FailNextResourceForTesting(stage);resource.Display(Frame(444+stage));bool failed=false;const auto started=GetTickCount64();while(!failed&&GetTickCount64()-started<3000){try{resource.Poll();}catch(const std::exception&){failed=true;}Sleep(10);}Check(failed,"Injected partial allocation failure observed");resource.Finish();const auto report=resource.Report();Check(report.find("\"created\":1")!=std::string::npos&&report.find("\"destroyed\":1")!=std::string::npos&&report.find("\"liveWindows\":0")!=std::string::npos,"Partial creation/capture HWND resources cleaned");Check(Windows(0).empty()&&Windows(444+stage).empty()&&IsWindow(sentinel),"No untracked HWND after resource failure");Check(std::filesystem::remove(captures),"Empty resource test directory removed");}
    Check(GetGuiResources(GetCurrentProcess(),GR_GDIOBJECTS)<=objects,"DIB and DC resources reclaimed after injected failure");
    wchar_t text[64]{};GetWindowTextW(sentinel,text,64);Check(lstrcmpW(text,L"12F outside sentinel")==0,"Outside title unchanged");DestroyWindow(sentinel);SetThreadDpiAwarenessContext(dpiContext);
    std::cout<<checks<<" native HWND, pixels, session isolation, input, Unicode, modality and cleanup checks PASS\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
